"""Original topAndRail against synthetic navigation state, retaining rail overflow CSS."""
from pathlib import Path
import json
r=Path(__file__).resolve().parents[2];o=r/'artifacts/replica/windows-download';src=(r/'docs/replica/source/original.js').read_text().splitlines();defs='\n'.join(s for s in src if s.startswith(('const stages=','const stageNames=','const icons=','const icon=','const t=','function topAndRail()')));stages=['connect','capabilities','select','review','running','results','save'];cases=[]
for lang in ['ko','en']:
 for height in [400,660,960]:
  for screen in ['home',*stages,'trial']:
   index=stages.index('select'if screen=='trial'else screen)if screen!='home'else -1
   cases.append(dict(lang=lang,height=height,width=220,screen=screen,visited=stages[:index+1]))
# Reopened sample result has only the result stage visited; moving backwards retains later visits.
for lang in ['ko','en']:
 for screen,visited in [('results',['results']),('select',stages),('trial',['select']),('running',stages)]:cases.append(dict(lang=lang,height=660,width=220,screen=screen,visited=visited))
for i,c in enumerate(cases):c['id']=str(i)
css=(r/'docs/replica/source/original.css').read_text();(o/'sidebar-original.css').write_text(css)
html='''<!doctype html><meta charset="utf-8"><title>Sidebar · original isolation</title><link rel="stylesheet" href="sidebar-original.css"><style>body{min-width:1600px}.fixture{position:absolute;left:30px}.fixture>.topbar{display:none}.fixture .rail{width:220px}</style><button id="sidebar-record" style="position:fixed;top:15px;right:20px">Record Sidebar</button><div id="fixtures"></div><script>let lang='ko';let state={};'''+defs+'\nconst cases='+json.dumps(cases,ensure_ascii=False)+''';for(const c of cases){lang=c.lang;state={screen:c.screen,visited:new Set(c.visited)};let w=document.createElement('section');w.className='fixture';w.dataset.id=c.id;if(c.id!=='0')w.setAttribute('aria-hidden','true');w.style.top=(30+Number(c.id)*1050)+'px';w.innerHTML=topAndRail();w.querySelector('.rail').style.height=c.height+'px';document.getElementById('fixtures').append(w)}document.getElementById('sidebar-record').onclick=async()=>{await document.fonts.ready;const rows=[...document.querySelectorAll('.fixture')].map(w=>{const rail=w.querySelector('.rail'),rect=rail.getBoundingClientRect(),box=x=>{let b=x.getBoundingClientRect();return{x:b.x-rect.x,y:b.y-rect.y,width:b.width,height:b.height}};return{id:w.dataset.id,width:rect.width,height:rect.height,clientWidth:rail.clientWidth,clientHeight:rail.clientHeight,scrollHeight:rail.scrollHeight,scrollWidth:rail.scrollWidth,title:box(rail.querySelector('.rail-title')),nav:box(rail.querySelector('nav')),navName:rail.querySelector('nav').getAttribute('aria-label'),note:box(rail.querySelector('.rail-note')),strong:box(rail.querySelector('strong')),noteText:rail.querySelector('.rail-note').innerText,titleText:rail.querySelector('.rail-title').innerText,items:[...rail.querySelectorAll('.step')].map(x=>({box:box(x),enabled:!x.disabled,current:x.getAttribute('aria-current')||'',done:x.classList.contains('done'),name:x.getAttribute('aria-label')||x.innerText.replaceAll('\\n',' '),key:x.dataset.action.slice(6)}))}});let response=await fetch('/evidence/source-sidebar.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dpr:devicePixelRatio,rows})});if(!response.ok)throw Error('Evidence failed');document.getElementById('sidebar-record').textContent='Sidebar recorded';};</script>'''
html=html.replace('<div id="fixtures"></div>', '<div style="position:fixed;left:300px;top:70px;z-index:20"><button id="sidebar-allvisits">All visits</button><button id="sidebar-running">Running</button><button id="sidebar-reopened">Reopened</button><button id="sidebar-locale">KO / EN</button><output id="sidebar-input-status"></output></div><div id="fixtures"></div>')
html=html.replace("let lang='ko';let state={};", "let lang='ko';let state={},requests=[],activeCase='55';")
extra=r"""function selectSidebar(id){activeCase=id;const c=cases.find(c=>c.id===id);lang=c.lang;state={screen:c.screen,visited:new Set(c.visited)};requests=[];for(const f of document.querySelectorAll('.fixture')){const active=f.dataset.id===id;f.style.visibility=active?'visible':'hidden';f.style.top=active?'30px':(30+Number(f.dataset.id)*1050)+'px';f.setAttribute('aria-hidden',String(!active))}document.getElementById('sidebar-input-status').textContent='Case '+id}for(const [id,offset]of [['sidebar-allvisits',1],['sidebar-running',3],['sidebar-reopened',0]])document.getElementById(id).onclick=()=>selectSidebar(String((lang==='ko'?54:58)+offset));document.getElementById('sidebar-locale').onclick=()=>selectSidebar(String(Number(activeCase)+(lang==='ko'?4:-4)));document.addEventListener('click',e=>{const b=e.target.closest('button[data-action]');if(!b||b.disabled||!b.dataset.action.startsWith('stage:'))return;const next=b.dataset.action.slice(6);if(state.screen==='running'||!state.visited.has(next))return;requests.push({key:next,trusted:e.isTrusted});document.getElementById('sidebar-input-status').textContent='Requested '+next});selectSidebar('55');"""
html=html.replace('JSON.stringify({dpr:devicePixelRatio,rows})','JSON.stringify({dpr:devicePixelRatio,rows,requests,activeCase})').replace('</script>',extra+'</script>')
(o/'sidebar.html').write_text(html)
for p in [o/'sidebar-cases.json',r/'docs/replica/source/sidebar-cases.json']:p.write_text(json.dumps(cases,ensure_ascii=False,indent=2)+'\n')
p=r/'tools/WindowsControl/fixture_server.py';s=p.read_text();s=s.replace("allowed={'source-resultchart.json'","allowed={'source-sidebar.json','source-resultchart.json'");p.write_text(s);print(len(cases),'source sidebar fixtures prepared')
